]

expected_demo = [
    [9, 9, 9, 4],
    [9, 9, 8, 9],
    [5, 4, 4, 8],
    [9, 4, 4, 4]
]

# NEW HYPOTHESIS: For output[j], collect ALL values at columns where c%4 == j
# Then apply SOME RULE (max/min/first/etc)
# Try ALL combinations of rule per position

def predict_with_all_offsets(row, rules):
    """
    For each output position j, collect all values at cols where col % 4 == j
    Apply rules[j] which is either 'max' or 'min' or 'first'
    """
    result = []

    # Group values by offset
    by_offset = {0: [], 1: [], 2: [], 3: []}
    for c, v in enumerate(row):
        if v != 0:  # Ignore zeros
            by_offset[c % 4].append(v)

    for j in range(4):
        vals = by_offset[j]
        if vals:
            if rules[j] == 'max':
                result.append(max(vals))
            elif rules[j] == 'min':
                result.append(min(vals))
            elif rules[j] == 'first':
                result.append(vals[0])
            else:
                result.append(0)
        else:
            result.append(0)

    return result

print("=== Trying all rule combinations ===\n")

best_combo = None
best_score = -1

for r0 in ['max', 'min', 'first']:
    for r1 in ['max', 'min', 'first']:
